import {
  breakpoints,
  color,
  font,
  fontVariable,
  layout,
  radius,
  semantic,
  shadow,
  typography,
} from './tokens.ts';

const px = (value: number) => `${value / 16}rem`;

/** Renders the Tailwind 4 theme (CSS-first config) from the tokens. */
export function renderThemeCss(): string {
  const lines: string[] = [
    '/* GENERATED by packages/config/scripts/build-css.ts from src/tokens.ts. Do not edit. */',
    '',
    '@theme {',
    '  /* Reset Tailwind defaults so only Casvitta tokens exist. */',
    '  --color-*: initial;',
    '  --font-*: initial;',
    '  --radius-*: initial;',
    '  --text-*: initial;',
    '  --breakpoint-*: initial;',
    '  --shadow-*: initial;',
    '',
    '  --color-transparent: transparent;',
    '  --color-current: currentColor;',
    '  --color-white: #FFFFFF;',
  ];
  for (const [name, hex] of Object.entries(color)) lines.push(`  --color-${name}: ${hex};`);
  lines.push('', '  /* Semantic aliases */');
  for (const [name, ref] of Object.entries(semantic))
    lines.push(`  --color-${name}: var(--color-${ref});`);

  lines.push('');
  for (const [name, stack] of Object.entries(font)) {
    lines.push(`  --font-${name}: var(${fontVariable[name as keyof typeof font]}), ${stack};`);
  }

  lines.push('');
  for (const [name, value] of Object.entries(radius)) lines.push(`  --radius-${name}: ${value}px;`);
  for (const [name, value] of Object.entries(shadow)) lines.push(`  --shadow-${name}: ${value};`);

  lines.push('');
  for (const [name, value] of Object.entries(breakpoints))
    lines.push(`  --breakpoint-${name}: ${px(value)};`);

  lines.push('');
  for (const [name, style] of Object.entries(typography)) {
    lines.push(`  --text-${name}: ${px(style.size)};`);
    lines.push(`  --text-${name}--line-height: ${px(style.lineHeight)};`);
    lines.push(`  --text-${name}--font-weight: ${style.weight};`);
    if ('tracking' in style) lines.push(`  --text-${name}--letter-spacing: ${style.tracking};`);
  }
  lines.push('}', '');

  // Layout measures (not Tailwind namespaces): use as w-(--layout-side-nav), max-w-(--layout-content).
  const content = layout.desktopRef - layout.sideNav - 2 * layout.margin;
  lines.push(
    ':root {',
    `  --layout-side-nav: ${layout.sideNav}px;`,
    `  --layout-content: ${content}px;`,
    '}',
    '',
  );

  lines.push('/* Type styles that need more than size/line-height/weight/tracking. */');
  for (const [name, style] of Object.entries(typography)) {
    const rules = [`font-family: var(--font-${style.family});`];
    if (style.family === 'mono') rules.push('font-variant-numeric: tabular-nums;');
    if ('uppercase' in style && style.uppercase) rules.push('text-transform: uppercase;');
    if (name === 'caption' || name === 'eyebrow') rules.push('color: var(--color-fg-muted);');
    if (name.startsWith('display') || name === 'title') rules.push('text-wrap: balance;');
    lines.push(
      `@utility type-${name} {`,
      `  font-size: var(--text-${name});`,
      `  line-height: var(--text-${name}--line-height);`,
      `  font-weight: var(--text-${name}--font-weight);`,
    );
    if ('tracking' in style) lines.push(`  letter-spacing: var(--text-${name}--letter-spacing);`);
    for (const rule of rules) lines.push(`  ${rule}`);
    lines.push('}');
  }
  lines.push('');
  return lines.join('\n');
}
